import Foundation
let titles = ["Парк", "Дом"]
var totalLength = 0
for title in titles {
    let length = autoreleasepool {
        NSMutableString(string: title).length
    }
    totalLength += length
}
print(totalLength)

Вывод 7. Нет намеренного хранения всех объектов в retained; это изменение владельцев, не доказательство объёма autorelease.
